    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-decoration-break"/>
    public CssKeyword? BoxDecorationBreak { init => Set("box-decoration-break", value); }

    /// <summary>旧版弹性盒中子元素排列方向是否反转（box-direction），已废弃，请用 flexDirection。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：子元素沿排列轴按正常顺序排列，对应 <c>flexDirection</c> 的 <c>row</c> 或 <c>column</c>；旧版弹性盒写法，已废弃。</description></item>
    /// <item><description><c>reverse</c>：子元素沿排列轴反向排列，对应 <c>flexDirection</c> 的 <c>row-reverse</c> 或 <c>column-reverse</c>；旧版弹性盒写法，已废弃。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-direction"/>
    public CssKeyword? BoxDirection { init => Set("box-direction", value); }

    /// <summary>旧版弹性盒中子元素的伸缩比例（box-flex），已废弃，请用 flexGrow。</summary>
    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>0</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-flex"/>
    public CssValue? BoxFlex { init => Set("box-flex", value, NumberUnit.Pixels); }

    /// <summary>旧版弹性盒中子元素的伸缩分组（box-flex-group），已废弃，浏览器基本不支持。</summary>
    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>1</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-flex-group"/>
    public CssValue? BoxFlexGroup { init => Set("box-flex-group", value, NumberUnit.Pixels); }

    /// <summary>旧版弹性盒是否允许换行（box-lines），已废弃，请用 flexWrap。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>multiple</c>：子元素放不下时可换到新的一行（列），对应 <c>flexWrap: 'wrap'</c>；旧版弹性盒写法，已废弃。</description></item>
    /// <item><description><c>single</c>：所有子元素排在同一行（列）内，不换行，对应 <c>flexWrap: 'nowrap'</c>；旧版弹性盒写法，已废弃。</description></item>
    /// </list>
    /// <para>初始值 <c>single</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-lines"/>
    public CssKeyword? BoxLines { init => Set("box-lines", value); }

    /// <summary>旧版弹性盒中子元素的显示顺序（box-ordinal-group），已废弃，请用 order。</summary>
    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>1</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-ordinal-group"/>
    public CssValue? BoxOrdinalGroup { init => Set("box-ordinal-group", value, NumberUnit.Pixels); }

    /// <summary>旧版弹性盒的排列轴向（box-orient），已废弃；多行截断时用 WebkitBoxOrient。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>block-axis</c>：子元素沿块轴排列，横排文字下等同于 <c>vertical</c>；旧版弹性盒写法，已废弃。</description></item>
    /// <item><description><c>horizontal</c>：子元素沿水平方向排列，对应 <c>flexDirection: 'row'</c>；旧版弹性盒写法，已废弃。</description></item>
    /// <item><description><c>inline-axis</c>：子元素沿行内轴排列，横排文字下等同于 <c>horizontal</c>；旧版弹性盒写法，已废弃。</description></item>
    /// <item><description><c>vertical</c>：子元素沿垂直方向排列，对应 <c>flexDirection: 'column'</c>；多行文本截断需配合 <c>WebkitBoxOrient: 'vertical'</c>。旧版弹性盒写法，已废弃。</description></item>
    /// </list>
    /// <para>初始值 <c>inline-axis</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-orient"/>
    public CssKeyword? BoxOrient { init => Set("box-orient", value); }

    /// <summary>设置盒子的外部或内部阴影，可叠加多层。（box-shadow）</summary>
    /// <remarks>
    /// <para>阴影不占布局空间，可用逗号叠加；与 border/outline 的用途和绘制位置不同。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不绘制盒子阴影，可用来清除其他规则设置的阴影。</description></item>
    /// </list>
    /// <para>适用场景：浮层层次、卡片边缘或内凹效果。</para>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-shadow"/>
    public CssValue? BoxShadow { init => Set("box-shadow", value, NumberUnit.Pixels); }

    /// <summary>决定 width、height 等尺寸是否包含内边距和边框。（box-sizing）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>content-box</c>：指定尺寸仅计算内容盒，内边距和边框额外增加外部尺寸。</description></item>
    /// <item><description><c>border-box</c>：指定尺寸包含内容、内边距和边框，但不包含外边距。仍不包含 margin；最小/最大尺寸和布局约束仍参与计算。content-box 在声明宽高之外再加内边距和边框。</description></item>
    /// </list>
    /// <para>适用场景：确定组件声明宽高时是否把 padding 和 border 算在尺寸内。</para>
    /// <para>初始值 <c>content-box</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/box-sizing"/>
    public CssKeyword? BoxSizing { init => Set("box-sizing", value); }

    /// <summary>旧版弹性盒中是否隐藏元素（box-suppress），草案属性，浏览器不支持。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>discard</c>：元素及其后代不生成盒子，效果近似 <c>display: none</c>。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>hide</c>：用于隐藏元素，与 <c>discard</c> 的具体区别以 CSS Display 草案为准。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>show</c>：元素按 <c>display</c> 正常生成盒子，即不做任何抑制，是默认值。早期草案属性，浏览器不支持。</description></item>
    /// </list>
    /// </remarks>
    public CssKeyword? BoxSuppress { init => Set("box-suppress", value); }

    /// <summary>设置元素之后的分页、分栏或区域分片行为。（break-after）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：既不强制也不禁止在该侧断开（<c>breakBefore</c> 指元素之前，<c>breakAfter</c> 指元素之后），由浏览器按内容自然决定。</description></item>
    /// <item><description><c>avoid</c>：尽量避免在该侧断开，不论是分页、分栏还是分区。</description></item>
    /// <item><description><c>avoid-column</c>：尽量避免在该侧分栏断开。</description></item>
    /// <item><description><c>avoid-page</c>：尽量避免在该侧分页断开。</description></item>
    /// <item><description><c>avoid-region</c>：尽量避免在该侧分区断开；属于 CSS Regions，浏览器基本不支持。</description></item>
    /// <item><description><c>column</c>：在该侧强制分栏，后续内容从下一栏开始。</description></item>
    /// <item><description><c>left</c>：在该侧强制分页，并使新起的一页是左页，必要时插入空白页；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>page</c>：在该侧强制分页，后续内容从新的一页开始；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>recto</c>：在该侧强制分页，并使新起的一页是正面页（从左到右书写时为右页，从右到左时为左页）；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>region</c>：在该侧强制切到下一个区域；属于 CSS Regions，浏览器基本不支持。</description></item>
    /// <item><description><c>right</c>：在该侧强制分页，并使新起的一页是右页，必要时插入空白页；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>verso</c>：在该侧强制分页，并使新起的一页是反面页（从左到右书写时为左页，从右到左时为右页）；主要用于分页媒体（如打印）。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2021 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/break-after"/>
    public CssKeyword? BreakAfter { init => Set("break-after", value); }

    /// <summary>设置元素之前的分页、分栏或区域分片行为。（break-before）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：既不强制也不禁止在该侧断开（<c>breakBefore</c> 指元素之前，<c>breakAfter</c> 指元素之后），由浏览器按内容自然决定。</description></item>
    /// <item><description><c>avoid</c>：尽量避免在该侧断开，不论是分页、分栏还是分区。</description></item>
    /// <item><description><c>avoid-column</c>：尽量避免在该侧分栏断开。</description></item>
    /// <item><description><c>avoid-page</c>：尽量避免在该侧分页断开。</description></item>
    /// <item><description><c>avoid-region</c>：尽量避免在该侧分区断开；属于 CSS Regions，浏览器基本不支持。</description></item>
    /// <item><description><c>column</c>：在该侧强制分栏，后续内容从下一栏开始。</description></item>
    /// <item><description><c>left</c>：在该侧强制分页，并使新起的一页是左页，必要时插入空白页；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>page</c>：在该侧强制分页，后续内容从新的一页开始；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>recto</c>：在该侧强制分页，并使新起的一页是正面页（从左到右书写时为右页，从右到左时为左页）；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>region</c>：在该侧强制切到下一个区域；属于 CSS Regions，浏览器基本不支持。</description></item>
    /// <item><description><c>right</c>：在该侧强制分页，并使新起的一页是右页，必要时插入空白页；主要用于分页媒体（如打印）。</description></item>
    /// <item><description><c>verso</c>：在该侧强制分页，并使新起的一页是反面页（从左到右书写时为左页，从右到左时为右页）；主要用于分页媒体（如打印）。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2021 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/break-before"/>
    public CssKeyword? BreakBefore { init => Set("break-before", value); }

    /// <summary>设置元素内部是否允许分页、分栏或区域分片。（break-inside）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：不限制元素内部断开，需要时可在内部分页、分栏或分区。</description></item>
    /// <item><description><c>avoid</c>：尽量避免在元素内部断开，不论是分页、分栏还是分区。</description></item>
    /// <item><description><c>avoid-column</c>：尽量避免在元素内部分栏断开，常用于防止卡片被拆到两栏。</description></item>
    /// <item><description><c>avoid-page</c>：尽量避免在元素内部分页断开，常用于打印时保持表格行、图片完整。</description></item>
    /// <item><description><c>avoid-region</c>：尽量避免在元素内部分区断开；属于 CSS Regions，浏览器基本不支持。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2021 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/break-inside"/>
    public CssKeyword? BreakInside { init => Set("break-inside", value); }

    /// <summary>设置表格标题相对于表格的放置侧。（caption-side）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>block-end</c>：标题放在表格块轴的结束侧，横排文字中即下方；较新的逻辑写法，浏览器支持有限。</description></item>
    /// <item><description><c>block-start</c>：标题放在表格块轴的起始侧，横排文字中即上方；较新的逻辑写法，浏览器支持有限。</description></item>
    /// <item><description><c>bottom</c>：标题放在表格下方。</description></item>
    /// <item><description><c>inline-end</c>：标题放在表格行内轴的结束侧，从左到右的横排中即右侧；较新的逻辑写法，浏览器支持有限。</description></item>
    /// <item><description><c>inline-start</c>：标题放在表格行内轴的起始侧，从左到右的横排中即左侧；较新的逻辑写法，浏览器支持有限。</description></item>
    /// <item><description><c>top</c>：标题放在表格上方，是默认值。</description></item>
    /// </list>
    /// <para>初始值 <c>top</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/caption-side"/>
    public CssKeyword? CaptionSide { init => Set("caption-side", value); }

    /// <summary>集中设置文本插入光标的颜色和形状。（caret）</summary>
    /// <remarks>
    /// <para>简写属性，初始值见各分项；继承。</para>
    /// </remarks>
    public CssColor? Caret { init => Set("caret", value); }

    /// <summary>设置可编辑内容中的文本插入光标颜色。（caret-color）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器选择光标颜色，通常跟随文本的 <c>color</c>。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/caret-color"/>
    public CssColor? CaretColor { init => Set("caret-color", value); }

    /// <summary>设置文本插入光标的形状。（caret-shape）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器选择光标形状，通常是竖条。</description></item>
    /// <item><description><c>bar</c>：竖条光标，画在字符之间。</description></item>
    /// <item><description><c>block</c>：方块光标，覆盖光标所在的字符。</description></item>
    /// <item><description><c>underscore</c>：下划线光标，画在光标所在字符的下方。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    public CssKeyword? CaretShape { init => Set("caret-shape", value); }

    /// <summary>要求元素避让指定侧的前置浮动元素。（clear）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>both</c>：避让左右两侧的前置浮动元素：元素下移到两侧浮动都结束之后。</description></item>
    /// <item><description><c>inline-end</c>：避让行内结束侧的前置浮动，从左到右的文本中即右浮动，从右到左的文本中即左浮动。</description></item>
    /// <item><description><c>inline-start</c>：避让行内起始侧的前置浮动，从左到右的文本中即左浮动，从右到左的文本中即右浮动。</description></item>
    /// <item><description><c>left</c>：避让左浮动元素：元素下移到左侧浮动结束之后。</description></item>
    /// <item><description><c>none</c>：不避让浮动，允许元素与前置浮动元素并排，是默认值。</description></item>
    /// <item><description><c>right</c>：避让右浮动元素：元素下移到右侧浮动结束之后。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/clear"/>
    public CssKeyword? Clear { init => Set("clear", value); }

    /// <summary>使用旧式矩形裁剪绝对定位元素；新代码优先考虑 clip-path。（clip）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：不裁剪，裁剪区域与元素的边框盒相同；<c>clip</c> 是旧属性，新代码用 <c>clipPath</c>。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；已废弃；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/clip"/>
    public CssKeyword? Clip { init => Set("clip", value); }

    /// <summary>通过基本形状、路径或引用裁剪元素的可见区域。（clip-path）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不裁剪，元素完整可见。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/clip-path"/>
    public CssKeyword? ClipPath { init => Set("clip-path", value); }

    /// <summary>设置 SVG 裁剪路径判断内部区域所用的填充规则。（clip-rule）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>evenodd</c>：按射线穿过路径次数的奇偶性判断内部，适合交叠或有孔路径。</description></item>
    /// <item><description><c>nonzero</c>：按有方向的绕数判断路径内部，子路径方向会影响结果。</description></item>
    /// </list>
    /// <para>初始值 <c>nonzero</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/clip-rule"/>
    public CssKeyword? ClipRule { init => Set("clip-rule", value); }

    /// <summary>设置文字前景色，同时作为 currentColor 的来源。（color）</summary>
    /// <remarks>
    /// <para>改变文字和 currentColor 的来源，不会自动改变背景。</para>
    /// <para>初始值 <c>canvastext</c>；继承；Baseline：2018 年起广泛可用。</para>
