    /// <summary>决定元素是否生成布局盒子，以及元素自身和内部内容如何排版。（display）</summary>
    /// <remarks>
    /// <para>外部显示类型决定元素自身以块级还是行内级方式参与周围布局；内部布局方式决定内容使用普通流、Flex 或 Grid 等布局。此属性不继承；例如 div 通常由浏览器默认样式设置为 block。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>block</c>：生成块级盒子，内部默认采用普通流布局。</description></item>
    /// <item><description><c>inline</c>：生成行内盒子，参与行内排版；普通非替换行内盒子的宽高不按块盒规则应用。</description></item>
    /// <item><description><c>flex</c>：生成块级弹性容器，直接子元素参与 Flex 布局。默认主轴为 row，默认不换行；主轴方向还受书写方向影响。inline-flex 使用相同的内部布局，但容器对外按行内级盒子排列。</description></item>
    /// <item><description><c>inline-flex</c>：创建行内级的 Flex 容器。子项换行由 flex-wrap 控制。当容器自身是 Flex/Grid 项目时，其外部排版还受父布局控制。与 flex 的区别是容器自身的外部排版方式，内部弹性布局机制相同；inline-flex 对应双关键字写法 inline flex。</description></item>
    /// <item><description><c>grid</c>：生成块级网格容器，直接子元素参与 Grid 布局。Flex 更侧重单个主轴；Grid 可以同时控制行和列。inline-grid 则改变容器对外的显示类型。</description></item>
    /// <item><description><c>none</c>：不生成元素及其后代的布局盒子，通常也从可访问性树中移除。不能靠它保留可聚焦交互；重新显示时需按组件需求管理焦点。visibility:hidden 通常保留布局空间；opacity:0 只改变透明度，通常仍能交互。</description></item>
    /// </list>
    /// <para>适用场景：选择容器的布局方式；具体对齐、间距和换行由对应布局属性控制。</para>
    /// <para>初始值 <c>inline</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/display"/>
    public CssKeyword? Display { init => Set("display", value); }

    /// <summary>单独设置 display 的内部布局方式（display-inside），早期草案，浏览器不支持；请用 display 的双值写法。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器按元素类型决定内部布局方式。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>block</c>：元素内部使用块布局（普通流）。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>flex</c>：元素内部使用弹性盒布局。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>grid</c>：元素内部使用网格布局。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>ruby</c>：元素内部使用 ruby 注音布局。早期草案属性，浏览器不支持。</description></item>
    /// <item><description><c>table</c>：元素内部使用表格布局。早期草案属性，浏览器不支持。</description></item>
    /// </list>
    /// </remarks>
    public CssKeyword? DisplayInside { init => Set("display-inside", value); }

