    /// <item><description><c>none</c>：元素不生成列表项标记，按普通盒子显示。早期草案属性，浏览器不支持。</description></item>
    /// </list>
    /// </remarks>
    public CssKeyword? DisplayList { init => Set("display-list", value); }

    /// <summary>单独设置 display 的外部显示类型（display-outside），早期草案，浏览器不支持。</summary>
    /// <remarks>
    /// <para>常用值：<c>block-level</c>、<c>contents</c>、<c>inline-level</c>、<c>none</c>、<c>ruby-base</c>、<c>ruby-base-container</c>、<c>ruby-text</c>、<c>ruby-text-container</c>、<c>run-in</c>、<c>table-caption</c>、<c>table-cell</c>、<c>table-column</c>、<c>table-column-group</c>、<c>table-footer-group</c>、<c>table-header-group</c>、<c>table-row</c>、<c>table-row-group</c></para>
    /// </remarks>
    public CssKeyword? DisplayOutside { init => Set("display-outside", value); }

    /// <summary>选择 SVG 文本布局的主导基线及基线表。（dominant-baseline）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>alphabetic</c>：以字母基线（拉丁字母底部）为主导基线，西文横排的常用对齐方式。</description></item>
    /// <item><description><c>auto</c>：由浏览器按书写模式选择：横排用字母基线，竖排且字形直立时用 <c>central</c>。</description></item>
    /// <item><description><c>central</c>：以字符 em 盒垂直方向的中心为主导基线，竖排文字常用。</description></item>
    /// <item><description><c>hanging</c>：以悬挂基线为主导基线，梵文、藏文等字形悬挂在这条线之下的文字使用。</description></item>
    /// <item><description><c>ideographic</c>：以表意基线为主导基线，位于 CJK 等表意文字字形的底部。</description></item>
    /// <item><description><c>mathematical</c>：以数学基线为主导基线，用于数学公式排版。</description></item>
    /// <item><description><c>middle</c>：以字母基线上方约半个 x 高度处为主导基线，常用来让文字在垂直方向居中。</description></item>
    /// <item><description><c>no-change</c>：沿用父元素的主导基线，不重新计算；SVG 1.1 旧值，已废弃。</description></item>
    /// <item><description><c>reset-size</c>：沿用父元素的主导基线，并按当前字号重新计算基线表；SVG 1.1 旧值，已废弃。</description></item>
    /// <item><description><c>text-after-edge</c>：以文本区域的下边缘为主导基线；SVG 1.1 旧值，已废弃，改用 <c>text-bottom</c>。</description></item>
    /// <item><description><c>text-before-edge</c>：以文本区域的上边缘为主导基线；SVG 1.1 旧值，已废弃，改用 <c>text-top</c>。</description></item>
    /// <item><description><c>use-script</c>：按文字所属书写系统选择默认基线；SVG 1.1 旧值，已废弃。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/dominant-baseline"/>
    public CssKeyword? DominantBaseline { init => Set("dominant-baseline", value); }

