    public CssKeyword? Filter { init => Set("filter", value); }

    /// <summary>集中设置弹性项目的增长系数、收缩系数和基础尺寸。（flex）</summary>
    /// <remarks>
    /// <para>依次对应 flex-grow、flex-shrink、flex-basis。作用于弹性项目，应先由父容器建立 Flex 布局。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：等价于 1 1 auto：可增长、可收缩，基础尺寸由主尺寸属性或内容决定。最终比例还受最小/最大尺寸约束，不保证所有项目等宽。1 1 0% 以零百分比为基础分配，auto 的基础尺寸通常受内容或主尺寸属性影响。</description></item>
    /// <item><description><c>none</c>：等价于 0 0 auto：不增长也不收缩，保留自动基础尺寸。auto 会增长和收缩；none 两者都不参与。</description></item>
    /// </list>
    /// <para>适用场景：分配弹性布局中的剩余空间，或让项目保持自身尺寸。</para>
    /// <para>数字值不加单位；简写属性，初始值见各分项；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex"/>
    public CssValue? Flex { init => Set("flex", value, NumberUnit.None); }

    /// <summary>设置弹性项目分配剩余空间之前的主轴基础尺寸。（flex-basis）</summary>
