    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：先参考主轴对应的 width 或 height；该值也为 auto 时由内容决定。</description></item>
    /// <item><description><c>content</c>：按内容确定基础尺寸，而不直接使用 width 或 height 作为基础尺寸。</description></item>
    /// </list>
    /// <para>适用场景：为侧栏、内容区或重复项目指定弹性分配的起始尺寸。</para>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>auto</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-basis"/>
    public CssLength? FlexBasis { init => Set("flex-basis", value); }

