    /// <remarks>
    /// <para>数值是分配正剩余空间的相对权重，不是最终宽度百分比。只有容器存在剩余空间时才发挥作用。</para>
    /// <para>适用场景：让主内容区填充工具栏或行布局的剩余空间。</para>
    /// <para>数字值不加单位；初始值 <c>0</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-grow"/>
    public CssValue? FlexGrow { init => Set("flex-grow", value, NumberUnit.None); }

    /// <summary>设置弹性项目空间不足时的收缩系数。（flex-shrink）</summary>
    /// <remarks>
    /// <para>实际收缩还与 flex-basis 成比例；自动最小尺寸可能阻止项目继续缩小。</para>
    /// <para>适用场景：控制空间不足时是否允许缩小；设置为 0 可避免图标或固定控件收缩。</para>
    /// <para>数字值不加单位；初始值 <c>1</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-shrink"/>
    public CssValue? FlexShrink { init => Set("flex-shrink", value, NumberUnit.None); }

    /// <summary>设置弹性项目是否换行，以及多行的排列方向。（flex-wrap）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>nowrap</c>：保持单行；项目仍可能收缩或溢出。</description></item>
    /// <item><description><c>wrap</c>：空间不足时形成多行，沿交叉轴正常方向排列。换行不会自动均分每行项目宽度，尺寸仍由各项目的 flex 配置决定。nowrap 保持单行；wrap-reverse 反转交叉轴上各行的排列方向。</description></item>
    /// <item><description><c>wrap-reverse</c>：允许换行并反转交叉轴上各行的排列方向。</description></item>
    /// </list>
    /// <para>适用场景：标签、按钮等项目不足一行时允许分行。</para>
    /// <para>初始值 <c>nowrap</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/flex-wrap"/>
    public CssKeyword? FlexWrap { init => Set("flex-wrap", value); }

    /// <summary>将元素浮动到指定侧，使相邻行内内容围绕它排列。（float）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>end</c>：StyleX 类型里保留的写法，浏览器不认；按书写方向靠结束边浮动请用 <c>inline-end</c>。</description></item>
    /// <item><description><c>inline-end</c>：元素浮动到行内结束侧，从左到右的文本中即右侧，其余内容在另一侧环绕。</description></item>
    /// <item><description><c>inline-start</c>：元素浮动到行内起始侧，从左到右的文本中即左侧，其余内容在另一侧环绕。</description></item>
    /// <item><description><c>left</c>：元素浮动到容器左侧，后续行内内容在其右侧环绕。</description></item>
    /// <item><description><c>none</c>：元素不浮动，保持在正常文档流中，是默认值。</description></item>
    /// <item><description><c>right</c>：元素浮动到容器右侧，后续行内内容在其左侧环绕。</description></item>
    /// <item><description><c>start</c>：StyleX 类型里保留的写法，浏览器不认；按书写方向靠起始边浮动请用 <c>inline-start</c>。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/float"/>
    public CssKeyword? Float { init => Set("float", value); }

    /// <summary>集中设置字体样式、粗细、大小、行高和字体族等信息。（font）</summary>
    /// <remarks>
    /// <para>简写属性，初始值见各分项；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font"/>
    public CssKeyword? Font { init => Set("font", value); }

    /// <summary>设置按优先级排列的字体族及通用字体回退。（font-family）</summary>
    /// <remarks>
    /// <para>初始值 <c>dependsOnUserAgent</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-family"/>
    public CssKeyword? FontFamily { init => Set("font-family", value); }

    /// <summary>通过 OpenType 特性标签控制字体的底层排版功能。（font-feature-settings）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不额外开关 OpenType 特性，按字体和其他 <c>font-*</c> 属性的默认排版。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-feature-settings"/>
    public CssKeyword? FontFeatureSettings { init => Set("font-feature-settings", value); }

    /// <summary>设置是否应用字体提供的字偶间距调整。（font-kerning）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器决定是否应用字偶间距调整，通常默认启用。</description></item>
    /// <item><description><c>none</c>：关闭字偶间距调整，字符按各自的默认字宽排列。</description></item>
    /// <item><description><c>normal</c>：强制启用字体提供的字偶间距调整。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-kerning"/>
    public CssKeyword? FontKerning { init => Set("font-kerning", value); }

    /// <summary>覆盖字体排版使用的语言系统标签，不改变文本实际语言。（font-language-override）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不覆盖，按文本实际语言（<c>lang</c>）选用字体的语言相关字形和规则。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-language-override"/>
    public CssKeyword? FontLanguageOverride { init => Set("font-language-override", value); }

    /// <summary>控制支持光学尺寸轴的字体是否按字号优化字形。（font-optical-sizing）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：浏览器按当前字号自动设置字体的光学尺寸轴（<c>opsz</c>），是默认值。</description></item>
    /// <item><description><c>none</c>：不自动调整光学尺寸，字形保持字体的默认光学尺寸。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-optical-sizing"/>
    public CssKeyword? FontOpticalSizing { init => Set("font-optical-sizing", value); }

    /// <summary>选择或覆盖彩色字体使用的调色板。（font-palette）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：使用字体的默认调色板。</description></item>
    /// <item><description><c>light</c>：使用字体中标明适合浅色背景的调色板，没有则退回默认调色板。</description></item>
    /// <item><description><c>dark</c>：使用字体中标明适合深色背景的调色板，没有则退回默认调色板。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-palette"/>
    public CssKeyword? FontPalette { init => Set("font-palette", value); }

    /// <summary>设置字体大小，也影响 em 等相对单位的计算。（font-size）</summary>
    /// <remarks>
    /// <para>改变字形大小，并影响 em 等相对长度；行盒高度还由 line-height 决定。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>math</c>：按 <c>math-depth</c> 对继承的字号做缩放，主要用于 MathML 上下标、分式等嵌套内容；较新的值，浏览器支持有限。</description></item>
    /// </list>
    /// <para>适用场景：建立文字层级，根字号相对尺寸可用 rem 表达。</para>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>medium</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-size"/>
    public CssLength? FontSize { init => Set("font-size", value); }

    /// <summary>按字体特征尺寸调整字号，减少字体回退造成的视觉变化。（font-size-adjust）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不按字体特征调整字号，使用声明的 <c>fontSize</c>。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>none</c>；继承；Baseline：2024 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-size-adjust"/>
    public CssValue? FontSizeAdjust { init => Set("font-size-adjust", value, NumberUnit.Pixels); }

    /// <summary>选择字体的宽窄字面；font-width 是其较新的名称。（font-stretch）</summary>
    /// <remarks>
    /// <para>初始值 <c>normal</c>；继承；已废弃；Baseline：2020 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-stretch"/>
    public CssKeyword? FontStretch { init => Set("font-stretch", value); }

    /// <summary>选择正常、斜体或倾斜字体样式。（font-style）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：使用字体的直立正体。</description></item>
    /// <item><description><c>italic</c>：使用字体的斜体字形；字体没有时退回倾斜字形，再没有则由浏览器合成。</description></item>
    /// <item><description><c>oblique</c>：使用倾斜字形，可后接角度，如 <c>oblique 10deg</c>；不写角度时默认为 <c>14deg</c>。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-style"/>
    public CssKeyword? FontStyle { init => Set("font-style", value); }

    /// <summary>控制缺少真实字体字形时浏览器可否合成粗体、斜体等样式。（font-synthesis）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：禁止浏览器合成任何缺失的粗体、斜体、小型大写和上下标字形，缺少时直接用字体已有的字形。</description></item>
    /// <item><description><c>weight</c>：字体没有粗体字形时，允许浏览器合成粗体；写在哪个值上，就允许合成哪一类。</description></item>
    /// <item><description><c>style</c>：字体没有斜体字形时，允许浏览器合成斜体。</description></item>
    /// <item><description><c>small-caps</c>：字体没有小型大写字形时，允许浏览器合成小型大写字母。</description></item>
    /// <item><description><c>position</c>：字体没有上标、下标字形时，允许浏览器缩小并平移普通字形来合成。</description></item>
    /// </list>
    /// <para>初始值 <c>weight style small-caps position </c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-synthesis"/>
    public CssKeyword? FontSynthesis { init => Set("font-synthesis", value); }

    /// <summary>控制浏览器是否可以合成上标和下标字形。（font-synthesis-position）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：字体没有上标、下标字形时，允许浏览器缩小并平移普通字形来合成。</description></item>
    /// <item><description><c>none</c>：禁止合成上标、下标字形，缺少时直接用字体已有的字形。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；继承；实验性；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-synthesis-position"/>
    public CssKeyword? FontSynthesisPosition { init => Set("font-synthesis-position", value); }

    /// <summary>控制浏览器是否可以合成小型大写字形。（font-synthesis-small-caps）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：字体没有原生小型大写字形时，允许浏览器缩小大写字母来合成小型大写。</description></item>
    /// <item><description><c>none</c>：禁止合成小型大写；字体没有原生字形时，按普通字形显示。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-synthesis-small-caps"/>
    public CssKeyword? FontSynthesisSmallCaps { init => Set("font-synthesis-small-caps", value); }

    /// <summary>控制浏览器是否可以合成倾斜字体。（font-synthesis-style）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：字体没有斜体或倾斜字形时，允许浏览器把直立字形倾斜，合成伪斜体。</description></item>
    /// <item><description><c>none</c>：禁止合成斜体，只使用字体自带的斜体字形；字体没有时保持直立。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-synthesis-style"/>
    public CssKeyword? FontSynthesisStyle { init => Set("font-synthesis-style", value); }

    /// <summary>控制浏览器是否可以合成加粗字体。（font-synthesis-weight）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：字体没有对应粗体字形时，允许浏览器加粗已有字形，合成伪粗体。</description></item>
    /// <item><description><c>none</c>：禁止合成粗体，只使用字体自带的字重；字体没有时保持原字重。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-synthesis-weight"/>
    public CssKeyword? FontSynthesisWeight { init => Set("font-synthesis-weight", value); }

    /// <summary>集中设置字体的连字、大小写、数字及其他变体。（font-variant）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：所有 <c>font-variant-*</c> 子属性都取 <c>normal</c>，不启用任何变体字形。</description></item>
    /// <item><description><c>none</c>：关闭所有连字（等同 <c>font-variant-ligatures: none</c>），其余子属性取 <c>normal</c>。</description></item>
    /// <item><description><c>historical-forms</c>：使用字体提供的历史字形（OpenType <c>hist</c>），属于 <c>font-variant-alternates</c> 的一部分。</description></item>
    /// <item><description><c>small-caps</c>：小写字母改用小型大写字形，大写字母保持不变。</description></item>
    /// <item><description><c>all-small-caps</c>：大写和小写字母都改用小型大写字形。</description></item>
    /// <item><description><c>petite-caps</c>：小写字母改用比小型大写更小的 petite 小型大写字形，需要字体提供 <c>pcap</c> 特性。</description></item>
    /// <item><description><c>all-petite-caps</c>：大写和小写字母都改用 petite 小型大写字形，需要字体提供 <c>c2pc</c> 特性。</description></item>
    /// <item><description><c>unicase</c>：大写字母改用小型大写字形，小写字母保持普通字形，得到大小写混合的统一视觉高度。</description></item>
    /// <item><description><c>titling-caps</c>：使用标题专用大写字形，笔画通常更纤细，避免全大写标题显得过重；需要字体提供 <c>titl</c> 特性。</description></item>
    /// <item><description><c>ordinal</c>：使用序数标记专用字形，如 1st、2nd 中上标的字母（OpenType <c>ordn</c>）。</description></item>
    /// <item><description><c>slashed-zero</c>：数字零带斜线，避免与大写字母 O 混淆（OpenType <c>zero</c>）。</description></item>
    /// <item><description><c>ruby</c>：使用适合注音（ruby）小字的东亚字形，主要影响日文假名（OpenType <c>ruby</c>）。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-variant"/>
    public CssKeyword? FontVariant { init => Set("font-variant", value); }

    /// <summary>选择字体提供的替代字形。（font-variant-alternates）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不启用任何替代字形，使用字体的默认字形。</description></item>
    /// <item><description><c>historical-forms</c>：使用字体提供的历史字形（OpenType <c>hist</c>），如旧式书写形态。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-variant-alternates"/>
    public CssKeyword? FontVariantAlternates { init => Set("font-variant-alternates", value); }

    /// <summary>设置小型大写等大小写字形变体。（font-variant-caps）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>all-petite-caps</c>：大写和小写字母都改用 petite 小型大写字形，需要字体提供 <c>c2pc</c> 特性。</description></item>
    /// <item><description><c>all-small-caps</c>：大写和小写字母都改用小型大写字形，需要字体提供 <c>c2sc</c> 特性。</description></item>
    /// <item><description><c>normal</c>：不使用小型大写等特殊字形，字母按自身大小写显示。</description></item>
    /// <item><description><c>petite-caps</c>：小写字母改用比小型大写更小的 petite 小型大写字形，需要字体提供 <c>pcap</c> 特性。</description></item>
    /// <item><description><c>small-caps</c>：小写字母改用小型大写字形，大写字母保持不变；字体缺少该特性时可能由浏览器合成。</description></item>
    /// <item><description><c>titling-caps</c>：使用标题专用大写字形，笔画通常更纤细，适合全大写的标题；需要字体提供 <c>titl</c> 特性。</description></item>
    /// <item><description><c>unicase</c>：大写字母改用小型大写字形，小写字母保持普通字形，得到大小写混合的统一视觉高度。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/font-variant-caps"/>
    public CssKeyword? FontVariantCaps { init => Set("font-variant-caps", value); }

    /// <summary>设置东亚文字字形及宽度变体。（font-variant-east-asian）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
