    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不定义运动路径，元素不沿路径移动。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-path"/>
    public CssKeyword? OffsetPath { init => Set("offset-path", value); }

    /// <summary>设置运动路径的初始位置。（offset-position）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不指定路径的起始位置，元素没有 offset 起点。</description></item>
    /// <item><description><c>auto</c>：以元素自身盒子所在的位置作为路径的起始位置。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；不继承；Baseline：2026 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-position"/>
    public CssKeyword? OffsetPosition { init => Set("offset-position", value); }

    /// <summary>设置元素沿运动路径移动时的方向和附加旋转。（offset-rotate）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：元素朝向跟随路径的切线方向旋转，可再叠加一个角度。</description></item>
    /// <item><description><c>reverse</c>：在 <c>auto</c> 基础上再旋转 180 度，使元素朝向与路径前进方向相反。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/offset-rotate"/>
    public CssKeyword? OffsetRotate { init => Set("offset-rotate", value); }

    /// <summary>设置元素及其子树合成后的整体不透明度。（opacity）</summary>
    /// <remarks>
    /// <para>0 完全透明，1 完全不透明；作用于整个子树的合成结果。透明元素仍可能接受点击和键盘焦点。</para>
    /// <para>适用场景：统一调整整个元素子树的透明度；只需背景半透明时应使用带 alpha 的背景色。</para>
    /// <para>数字值不加单位；初始值 <c>1</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/opacity"/>
    public CssValue? Opacity { init => Set("opacity", value, NumberUnit.None); }

    /// <summary>设置 Flex 或 Grid 项目的视觉排列顺序，不改变 DOM 顺序。（order）</summary>
    /// <remarks>
    /// <para>不改变源代码、朗读及通常的 Tab 顺序，避免用视觉重排破坏阅读顺序。</para>
    /// <para>数字值不加单位；初始值 <c>0</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/order"/>
    public CssValue? Order { init => Set("order", value, NumberUnit.None); }

    /// <summary>设置分页或分栏断点前需保留的最少行数。（orphans）</summary>
