    /// <para>数字值不加单位；初始值 <c>2</c>；继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/orphans"/>
    public CssValue? Orphans { init => Set("orphans", value, NumberUnit.None); }

    /// <summary>设置盒子外围轮廓线的宽度、线型和颜色，不占布局空间。（outline）</summary>
