    /// <para>简写属性，初始值见各分项；不继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/outline"/>
    public CssValue? Outline { init => Set("outline", value, NumberUnit.Pixels); }

