    /// <item><description><c>auto</c>：由浏览器自行选择轮廓颜色，通常与系统强调色或焦点环配色一致。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/outline-color"/>
    public CssColor? OutlineColor { init => Set("outline-color", value); }

    /// <summary>设置轮廓线与边框边缘之间的距离。（outline-offset）</summary>
    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>0</c>；不继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/outline-offset"/>
    public CssLength? OutlineOffset { init => Set("outline-offset", value); }

