    /// <item><description><c>none</c>：该元素及其后代不会被选作滚动锚点，不参与自动保持滚动位置。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2026 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-anchor"/>
    public CssKeyword? OverflowAnchor { init => Set("overflow-anchor", value); }

    /// <summary>设置逻辑块轴上的溢出行为。（overflow-block）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>visible</c>：允许内容绘制到盒子外；与另一轴的设置组合时计算值可能变化。</description></item>
    /// <item><description><c>hidden</c>：裁剪溢出且不显示滚动条，但仍是可通过脚本等方式滚动的滚动容器。可能成为 sticky 后代的滚动参照，不能把它仅理解成视觉裁剪。clip 不建立滚动容器；hidden 仍可通过脚本或焦点移动滚动。</description></item>
    /// <item><description><c>clip</c>：在裁剪边界截断内容，不建立滚动容器，也不支持程序化滚动。两轴设置会影响计算结果；与另一轴 auto/scroll 等组合时，要检查最终溢出行为。与 hidden 不同，不支持程序化滚动，也不单独建立块格式化上下文。</description></item>
    /// <item><description><c>auto</c>：按溢出情况提供滚动机制；滚动条外观和是否占空间由环境决定。scroll 通常始终预留或显示滚动机制；auto 根据溢出情况显示滚动条，外观由平台决定。</description></item>
    /// <item><description><c>scroll</c>：建立滚动容器，通常即使未溢出也显示滚动条；具体外观由平台决定。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2025 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-block"/>
    public CssKeyword? OverflowBlock { init => Set("overflow-block", value); }

    /// <summary>设置 overflow:clip 的裁剪边界允许向外扩展的距离。（overflow-clip-margin）</summary>
    /// <remarks>
    /// <para>初始值 <c>0px</c>；不继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-clip-margin"/>
    public CssKeyword? OverflowClipMargin { init => Set("overflow-clip-margin", value); }

    /// <summary>设置不可正常断开的长文本是否允许额外换行。（overflow-wrap）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：只使用正常换行机会，不为长单词额外断行。</description></item>
    /// <item><description><c>anywhere</c>：必要时允许在长文本任意位置断行，这些机会参与 min-content 尺寸计算。break-word 的额外断点不按 anywhere 的方式参与最小内容宽度计算；word-break:break-all 更积极地拆分普通单词。</description></item>
    /// <item><description><c>break-word</c>：必要时允许长文本断行，但新增断点不按 anywhere 的方式参与 min-content 计算。</description></item>
    /// </list>
    /// <para>适用场景：防止 URL、标识符等长文本撑破容器。</para>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2021 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-wrap"/>
    public CssKeyword? OverflowWrap { init => Set("overflow-wrap", value); }

