    public CssKeyword? PlaceSelf { init => Set("place-self", value); }

    /// <summary>设置元素何时可以成为指针命中目标；SVG 还支持按填充和描边命中。（pointer-events）</summary>
    /// <remarks>
    /// <para>控制指针命中，不等同于原生 disabled，也不会单独阻止键盘交互。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：采用当前元素类型的默认命中规则。</description></item>
    /// <item><description><c>none</c>：元素本身不成为指针命中目标；不等于禁用，仍可能通过 Tab 获焦，后代也可恢复命中。后代可以恢复命中；来自后代的事件仍可能经过祖先监听器。</description></item>
    /// </list>
    /// <para>适用场景：允许指针穿过装饰层；可交互控件的禁用应同时处理行为和语义。</para>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/pointer-events"/>
    public CssKeyword? PointerEvents { init => Set("pointer-events", value); }

    /// <summary>设置元素的定位方式，并决定偏移属性如何参与布局。（position）</summary>
    /// <remarks>
    /// <para>偏移通常通过 top/right/bottom/left 或逻辑 inset 属性设置。fixed 和 absolute 的包含块也可能由 transform 等属性建立。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>static</c>：参与普通文档流，top/right/bottom/left 等定位偏移不生效。</description></item>
    /// <item><description><c>relative</c>：保留普通流中的原位置，再按偏移移动绘制位置；不会为偏移后的区域重新排版。absolute 会脱离普通流；relative 仍保留原占位。</description></item>
    /// <item><description><c>absolute</c>：脱离普通文档流，按包含块定位；包含块通常由定位祖先或 transform 等属性建立。通常在预期的容器上设置 position:relative；元素不为自己保留普通流占位。</description></item>
    /// <item><description><c>fixed</c>：脱离普通流，通常相对视口固定；某些祖先属性会建立不同的包含块。祖先的 transform 等属性可能改变固定定位的包含块；z-index 仍受层叠上下文约束。absolute 通常跟随其包含块滚动；fixed 在以视口为包含块时保持视口位置。</description></item>
    /// <item><description><c>sticky</c>：保留流内位置，在滚动范围内按 inset 约束吸附。对应轴至少一个 inset 须非 auto，并受滚动祖先和包含块限制。对应轴至少一个 inset 必须非 auto；祖先 overflow 可能改变滚动参照。与 fixed 不同，它保留流内占位，并受自身所在包含块的范围约束。</description></item>
    /// </list>
    /// <para>适用场景：建立定位参照、覆盖层、固定区域或滚动吸附内容。</para>
    /// <para>初始值 <c>static</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position"/>
    public CssKeyword? Position { init => Set("position", value); }

