    /// <item><description><c>normal</c>：初始值，不指定显式锚点；默认锚点由规范的隐式锚点规则决定，不同上下文下行为有差异。</description></item>
    /// <item><description><c>auto</c>：使用元素的隐式锚点作为默认锚点，例如 popover 的触发元素。</description></item>
    /// <item><description><c>none</c>：元素没有默认锚点，也不使用隐式锚点。</description></item>
    /// <item><description><c>match-parent</c>：默认锚点沿用父元素 <c>position-anchor</c> 的计算结果，较新，使用前核对浏览器支持。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；不继承；实验性；Baseline：2026 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/position-anchor"/>
    public CssKeyword? PositionAnchor { init => Set("position-anchor", value); }

