    /// <list type="bullet">
    /// <item><description><c>auto</c>：使用平台默认的滚动条宽度。</description></item>
    /// <item><description><c>none</c>：隐藏滚动条，但内容仍可通过滚轮、触摸等方式滚动。</description></item>
    /// <item><description><c>thin</c>：使用更细的滚动条，具体宽度由平台决定。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2024 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/scrollbar-width"/>
    public CssKeyword? ScrollbarWidth { init => Set("scrollbar-width", value); }

