    /// <para>数字值不加单位；初始值 <c>0.0</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/shape-image-threshold"/>
    public CssValue? ShapeImageThreshold { init => Set("shape-image-threshold", value, NumberUnit.None); }

