    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>0</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/shape-margin"/>
    public CssLength? ShapeMargin { init => Set("shape-margin", value); }

    /// <summary>设置浮动元素周围行内内容所环绕的形状。（shape-outside）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不使用自定义形状，行内内容按浮动元素的外边距盒环绕。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/shape-outside"/>
    public CssKeyword? ShapeOutside { init => Set("shape-outside", value); }

