    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器权衡速度与精度，通常开启抗锯齿。</description></item>
    /// <item><description><c>crispEdges</c>：优先边缘清晰，通常关闭抗锯齿，适合横平竖直的线条和像素风图形。</description></item>
    /// <item><description><c>geometricPrecision</c>：优先几何精度，缩放时形状保持准确，不为速度牺牲平滑度。</description></item>
    /// <item><description><c>optimizeSpeed</c>：优先渲染速度，可能关闭抗锯齿，换取更快的绘制。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/shape-rendering"/>
    public CssKeyword? ShapeRendering { init => Set("shape-rendering", value); }

