    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：旧版 CSS Speech 值：由元素是否被渲染（<c>display</c>、<c>visibility</c>）推导是否朗读。已废弃，浏览器基本不支持。</description></item>
    /// <item><description><c>none</c>：语音合成不朗读该元素内容。已废弃，浏览器基本不支持。</description></item>
    /// <item><description><c>normal</c>：语音合成以正常方式朗读该元素内容。已废弃，浏览器基本不支持。</description></item>
    /// </list>
    /// <para>Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    public CssKeyword? Speak { init => Set("speak", value); }

    /// <summary>设置语音呈现时文字、数字和标点的朗读方式；使用前核对语音媒体支持。（speak-as）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：按所在语言的常规规则朗读文字、数字和标点。</description></item>
    /// <item><description><c>spell-out</c>：逐字母拼读，适合缩写词、代码等。</description></item>
    /// <item><description><c>digits</c>：数字逐位朗读，如 “123” 读成“一二三”而非“一百二十三”。</description></item>
    /// <item><description><c>literal-punctuation</c>：把标点符号的名称读出来，如读出“逗号”。</description></item>
    /// <item><description><c>no-punctuation</c>：不朗读标点，也不因标点产生停顿。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；实验性；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    public CssKeyword? SpeakAs { init => Set("speak-as", value); }

