    /// <para>简写属性，初始值见各分项；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke"/>
    public CssColor? Stroke { init => Set("stroke", value); }

