    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：描边是连续的实线，不使用虚线。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-dasharray"/>
    public CssValue? StrokeDasharray { init => Set("stroke-dasharray", value, NumberUnit.None); }

