    /// <remarks>
    /// <para>数字值不加单位；初始值 <c>0</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-dashoffset"/>
    public CssValue? StrokeDashoffset { init => Set("stroke-dashoffset", value, NumberUnit.None); }

