    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>butt</c>：在端点处平直截断描边，不向外延伸。</description></item>
    /// <item><description><c>round</c>：使用半圆端帽，向端点外延伸半个描边宽度。</description></item>
    /// <item><description><c>square</c>：使用方形端帽，向端点外延伸半个描边宽度。</description></item>
    /// </list>
    /// <para>初始值 <c>butt</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-linecap"/>
    public CssKeyword? StrokeLinecap { init => Set("stroke-linecap", value); }

    /// <summary>设置 SVG 路径转角处描边的连接形状。（stroke-linejoin）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>bevel</c>：转角处削平成斜切面，形成平直的连接。</description></item>
    /// <item><description><c>miter</c>：延长两条边的外缘形成尖角；尖角过长（超过 <c>stroke-miterlimit</c>）时回退为斜切。</description></item>
    /// <item><description><c>round</c>：转角处用圆弧连接，圆弧半径为描边宽度的一半。</description></item>
    /// </list>
    /// <para>初始值 <c>miter</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-linejoin"/>
    public CssKeyword? StrokeLinejoin { init => Set("stroke-linejoin", value); }

    /// <summary>限制尖角连接的延伸比例，超过阈值时改变连接形状。（stroke-miterlimit）</summary>
    /// <remarks>
    /// <para>数字值不加单位；初始值 <c>4</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-miterlimit"/>
    public CssValue? StrokeMiterlimit { init => Set("stroke-miterlimit", value, NumberUnit.None); }

    /// <summary>设置 SVG 描边的不透明度，不影响填充。（stroke-opacity）</summary>
    /// <remarks>
    /// <para>数字值不加单位；初始值 <c>1</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-opacity"/>
    public CssValue? StrokeOpacity { init => Set("stroke-opacity", value, NumberUnit.None); }

