    /// <remarks>
    /// <para>数字值不加单位；初始值 <c>1px</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/stroke-width"/>
    public CssValue? StrokeWidth { init => Set("stroke-width", value, NumberUnit.None); }

