    /// <para>数字值不加单位；初始值 <c>8</c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/tab-size"/>
    public CssValue? TabSize { init => Set("tab-size", value, NumberUnit.None); }

