    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>start</c>：按当前书写方向的行内起始侧对齐。</description></item>
    /// <item><description><c>end</c>：按当前书写方向的行内结束侧对齐。</description></item>
    /// <item><description><c>center</c>：将行内内容在行盒中居中，不会让块盒自身居中。</description></item>
    /// <item><description><c>justify</c>：调整行内间距使文字两端对齐；最后一行通常由 text-align-last 控制。</description></item>
    /// </list>
    /// <para>适用场景：正文、标题和表格单元格中的文本对齐。</para>
    /// <para>初始值 <c>startOrNamelessValueIfLTRRightIfRTL</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-align"/>
    public CssKeyword? TextAlign { init => Set("text-align", value); }

    /// <summary>设置段落最后一行或强制换行前一行的对齐方式。（text-align-last）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：最后一行跟随 <c>text-align</c>；<c>text-align</c> 为 <c>justify</c> 时，最后一行按 <c>start</c> 对齐。</description></item>
    /// <item><description><c>center</c>：最后一行在行盒中居中。</description></item>
    /// <item><description><c>end</c>：最后一行按书写方向的行内结束侧对齐。</description></item>
    /// <item><description><c>justify</c>：最后一行也两端对齐，拉伸到占满整行。</description></item>
    /// <item><description><c>left</c>：最后一行靠物理左侧对齐。</description></item>
    /// <item><description><c>right</c>：最后一行靠物理右侧对齐。</description></item>
    /// <item><description><c>start</c>：最后一行按书写方向的行内起始侧对齐。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2025 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-align-last"/>
    public CssKeyword? TextAlignLast { init => Set("text-align-last", value); }

