    /// <para>初始值 <c>currentcolor</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-decoration-color"/>
    public CssColor? TextDecorationColor { init => Set("text-decoration-color", value); }

    /// <summary>设置下划线、上划线或删除线等装饰线位置。（text-decoration-line）</summary>
