    /// <item><description><c>auto</c>：由浏览器决定：通常在笔画穿过装饰线处断开，对中日韩等文字可能不断开。</description></item>
    /// <item><description><c>none</c>：装饰线连续绘制，直接穿过字形。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-decoration-skip-ink"/>
    public CssKeyword? TextDecorationSkipInk { init => Set("text-decoration-skip-ink", value); }

    /// <summary>设置文本装饰线的实线、波浪线等线型。（text-decoration-style）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>solid</c>：实线。</description></item>
    /// <item><description><c>double</c>：双线，两条平行的线。</description></item>
    /// <item><description><c>dotted</c>：点线。</description></item>
    /// <item><description><c>dashed</c>：虚线。</description></item>
    /// <item><description><c>wavy</c>：波浪线，常用来表示拼写错误。</description></item>
    /// </list>
    /// <para>初始值 <c>solid</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-decoration-style"/>
    public CssKeyword? TextDecorationStyle { init => Set("text-decoration-style", value); }

    /// <summary>设置文本装饰线粗细。（text-decoration-thickness）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器决定装饰线粗细，通常取字体建议值或按字号推算。</description></item>
    /// <item><description><c>from-font</c>：使用字体文件中指定的装饰线粗细；字体没有提供时回退为 <c>auto</c>。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>auto</c>；不继承；Baseline：2023 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-decoration-thickness"/>
    public CssLength? TextDecorationThickness { init => Set("text-decoration-thickness", value); }

    /// <summary>同时设置文字着重号的样式和颜色。（text-emphasis）</summary>
    /// <remarks>
    /// <para>简写属性，初始值见各分项；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-emphasis"/>
    public CssColor? TextEmphasis { init => Set("text-emphasis", value); }

    /// <summary>设置文字着重号颜色。（text-emphasis-color）</summary>
    /// <remarks>
    /// <para>初始值 <c>currentcolor</c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-emphasis-color"/>
    public CssColor? TextEmphasisColor { init => Set("text-emphasis-color", value); }

    /// <summary>设置文字着重号位于文字的哪一侧。（text-emphasis-position）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器按书写模式和语言选择着重号位置。</description></item>
    /// <item><description><c>over</c>：横排时着重号在文字上方；竖排时与 <c>right</c>、<c>left</c> 组合确定侧边。</description></item>
    /// <item><description><c>under</c>：横排时着重号在文字下方；竖排时与 <c>right</c>、<c>left</c> 组合确定侧边。</description></item>
    /// <item><description><c>right</c>：竖排时着重号在文字右侧，与 <c>over</c>、<c>under</c> 组合使用。</description></item>
    /// <item><description><c>left</c>：竖排时着重号在文字左侧，与 <c>over</c>、<c>under</c> 组合使用。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-emphasis-position"/>
    public CssKeyword? TextEmphasisPosition { init => Set("text-emphasis-position", value); }

    /// <summary>设置文字着重号的形状和填充方式。（text-emphasis-style）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不显示着重号。</description></item>
    /// <item><description><c>filled</c>：实心着重号；只写 <c>filled</c> 不写形状时，横排默认 <c>dot</c>，竖排默认 <c>sesame</c>。</description></item>
    /// <item><description><c>open</c>：空心着重号；只写 <c>open</c> 不写形状时，横排默认 <c>dot</c>，竖排默认 <c>sesame</c>。</description></item>
    /// <item><description><c>dot</c>：小圆点形状的着重号，实心为 •，空心为 ◦。</description></item>
    /// <item><description><c>circle</c>：大圆形状的着重号，实心为 ●，空心为 ○。</description></item>
    /// <item><description><c>double-circle</c>：双圈形状的着重号，实心为 ◉，空心为 ◎。</description></item>
    /// <item><description><c>triangle</c>：三角形形状的着重号，实心为 ▲，空心为 △。</description></item>
    /// <item><description><c>sesame</c>：芝麻点形状的着重号，形似逗号，常用于日文竖排。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；继承；Baseline：2024 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-emphasis-style"/>
    public CssKeyword? TextEmphasisStyle { init => Set("text-emphasis-style", value); }

    /// <summary>设置文本行的缩进距离。（text-indent）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>hanging</c>：反转缩进：首行不缩进，其余各行缩进，形成悬挂缩进。</description></item>
    /// <item><description><c>each-line</c>：缩进不仅作用于块的首行，也作用于每个强制换行之后的行。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>0</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-indent"/>
    public CssLength? TextIndent { init => Set("text-indent", value); }

    /// <summary>设置两端对齐时增加间距的算法。（text-justify）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器选择两端对齐算法，在速度与效果之间取舍。</description></item>
    /// <item><description><c>distribute</c>：已废弃，等同 <c>inter-character</c>，改用 <c>inter-character</c>。</description></item>
    /// <item><description><c>inter-character</c>：把多余空间分配到字符之间，适合不靠空格分词的中日文。</description></item>
    /// <item><description><c>inter-word</c>：只在单词（空格）之间分配多余空间，适合英文等以空格分词的文字。</description></item>
    /// <item><description><c>none</c>：禁用两端对齐，即使 <c>text-align: justify</c> 也不拉伸间距。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-justify"/>
    public CssKeyword? TextJustify { init => Set("text-justify", value); }

    /// <summary>设置竖排模式下字符的方向。（text-orientation）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>mixed</c>：竖排中拉丁字母等横排文字顺时针旋转 90° 躺倒，全角字符保持直立。</description></item>
    /// <item><description><c>sideways</c>：所有字符都顺时针旋转 90° 躺倒，如同把横排文字整体旋转。</description></item>
    /// <item><description><c>upright</c>：所有字符都保持直立，包括拉丁字母，逐字自上而下排列。</description></item>
    /// </list>
    /// <para>初始值 <c>mixed</c>；继承；Baseline：2023 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-orientation"/>
    public CssKeyword? TextOrientation { init => Set("text-orientation", value); }

    /// <summary>设置被裁剪的行内溢出文本如何提示，例如显示省略号。（text-overflow）</summary>
    /// <remarks>
    /// <para>本属性不自行制造溢出。单行省略通常还需要受限宽度、overflow:hidden 和 white-space:nowrap。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>ellipsis</c>：用省略号提示被裁剪的行内溢出；还需要限制尺寸并配置溢出规则。不会自动限制宽度、禁用换行或实现多行省略。Flex/Grid 子项还可能需要 min-width:0。</description></item>
    /// <item><description><c>clip</c>：直接裁剪溢出文本，不添加省略标记。</description></item>
    /// </list>
    /// <para>适用场景：受限宽度中的单行标题或标签。多行截断需要单独的布局和截行方案。</para>
    /// <para>初始值 <c>clip</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-overflow"/>
    public CssKeyword? TextOverflow { init => Set("text-overflow", value); }

    /// <summary>向渲染器提供文本速度、可读性或几何精度的偏好。（text-rendering）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器自行权衡速度、可读性和精度，各引擎的策略不同。</description></item>
    /// <item><description><c>geometricPrecision</c>：优先几何精度，缩放时字形与间距更准确，可能增加渲染开销。</description></item>
    /// <item><description><c>optimizeLegibility</c>：优先可读性，启用字距调整、连字等排版特性，可能牺牲速度。</description></item>
    /// <item><description><c>optimizeSpeed</c>：优先渲染速度，可能关闭字距调整和连字。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-rendering"/>
    public CssKeyword? TextRendering { init => Set("text-rendering", value); }

    /// <summary>设置文字及其装饰的阴影，可叠加多层。（text-shadow）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不添加文字阴影。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-shadow"/>
    public CssValue? TextShadow { init => Set("text-shadow", value, NumberUnit.Pixels); }

    /// <summary>控制移动浏览器为提升可读性而进行的文字自动放大。（text-size-adjust）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：禁止浏览器自动调整文字大小。</description></item>
    /// <item><description><c>auto</c>：允许浏览器按其算法自动放大文字，常见于移动端未适配视口的页面。</description></item>
    /// </list>
    /// <para>初始值 <c>autoForSmartphoneBrowsersSupportingInflation</c>；继承；实验性；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-size-adjust"/>
    public CssKeyword? TextSizeAdjust { init => Set("text-size-adjust", value); }

    /// <summary>设置文字显示时的大小写、全角或其他字形转换。（text-transform）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>capitalize</c>：把每个单词的首字母转为大写，其余字母不变；具体规则随语言而定。</description></item>
    /// <item><description><c>full-width</c>：把字符转为全角形式，使半角字符与东亚字符等宽排列。</description></item>
    /// <item><description><c>lowercase</c>：把所有字母转为小写。</description></item>
    /// <item><description><c>none</c>：不转换大小写，按原文显示。</description></item>
    /// <item><description><c>uppercase</c>：把所有字母转为大写。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-transform"/>
    public CssKeyword? TextTransform { init => Set("text-transform", value); }

    /// <summary>设置下划线相对于默认位置的偏移。（text-underline-offset）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器决定下划线与默认位置的偏移，通常依字体指标确定。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>auto</c>；继承；Baseline：2023 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-underline-offset"/>
    public CssLength? TextUnderlineOffset { init => Set("text-underline-offset", value); }

    /// <summary>设置下划线相对于文字基线或竖排文字的放置方式。（text-underline-position）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：由浏览器选择下划线位置，通常靠近基线。</description></item>
    /// <item><description><c>from-font</c>：使用字体提供的下划线位置；字体没有提供时回退为 <c>auto</c>。</description></item>
    /// <item><description><c>under</c>：下划线放在文字下缘之下，避免穿过下伸部分。</description></item>
    /// <item><description><c>left</c>：竖排时下划线位于文字左侧，横排时无效。</description></item>
    /// <item><description><c>right</c>：竖排时下划线位于文字右侧，横排时无效。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；继承；Baseline：2023 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-underline-position"/>
    public CssKeyword? TextUnderlinePosition { init => Set("text-underline-position", value); }

    /// <summary>同时设置文本是否换行及换行策略。（text-wrap）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>wrap</c>：允许软换行。</description></item>
    /// <item><description><c>nowrap</c>：禁止软换行，但不取消显式强制换行。</description></item>
    /// <item><description><c>balance</c>：尝试让各行长度更均衡，常用于标题；可处理行数由浏览器决定。</description></item>
    /// <item><description><c>pretty</c>：使用偏向排版质量的换行策略，例如减少末行孤立短词。</description></item>
    /// <item><description><c>stable</c>：编辑时尽量不改变较早行的换行位置。</description></item>
    /// </list>
    /// <para>初始值 <c>wrap</c>；继承；Baseline：2026 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/text-wrap"/>
    public CssKeyword? TextWrap { init => Set("text-wrap", value); }

    /// <summary>扩大命名动画时间线的可引用作用域。（timeline-scope）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不扩大任何时间线名称的作用域，名称只在声明它的元素子树内可引用。</description></item>
    /// </list>
    /// <para>初始值 <c>none</c>；不继承；实验性；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/timeline-scope"/>
    public CssKeyword? TimelineScope { init => Set("timeline-scope", value); }

    /// <summary>设置定位元素相对于其定位参照的上侧偏移。（top）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：不指定该侧偏移：绝对定位时位置由对侧偏移、元素尺寸或静态位置决定，相对定位时按 0 处理。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>auto</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/top"/>
    public CssLength? Top { init => Set("top", value); }

    /// <summary>声明浏览器可以处理的触摸平移与缩放手势。（touch-action）</summary>
    /// <remarks>
    /// <para>描述浏览器可接管的触摸手势，手势开始后再修改通常不会改变当前手势的处理。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>manipulation</c>：允许平移和连续缩放，通常禁用双击缩放等额外手势。</description></item>
    /// <item><description><c>pan-x</c>：允许浏览器处理水平单指平移。</description></item>
    /// <item><description><c>pan-y</c>：允许浏览器处理垂直单指平移。</description></item>
    /// <item><description><c>none</c>：禁用浏览器在该区域处理的平移和缩放手势，可能影响用户缩放可访问性。</description></item>
    /// </list>
    /// <para>适用场景：拖拽控件与页面滚动之间分配触摸方向；保留用户所需的缩放能力。</para>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/touch-action"/>
    public CssKeyword? TouchAction { init => Set("touch-action", value); }

    /// <summary>按顺序组合平移、旋转、缩放等二维或三维变换。（transform）</summary>
    /// <remarks>
    /// <para>多个变换的顺序会影响结果。变换通常不改变元素在普通文档流中预留的尺寸。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不应用任何变换。</description></item>
    /// </list>
    /// <para>适用场景：平移、旋转和缩放的视觉效果；需要改变普通流占位时应调整布局属性。</para>
    /// <para>初始值 <c>none</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform"/>
    public CssKeyword? Transform { init => Set("transform", value); }

    /// <summary>设置变换及其原点所依据的参照盒。（transform-box）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>border-box</c>：以边框盒为参照盒；没有 CSS 盒的 SVG 元素按 <c>stroke-box</c> 处理。</description></item>
    /// <item><description><c>fill-box</c>：以 SVG 元素对象的包围盒为参照盒，不含描边。</description></item>
    /// <item><description><c>view-box</c>：以最近的 SVG 视口的 <c>viewBox</c> 为参照盒。</description></item>
    /// </list>
    /// <para>初始值 <c>view-box</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/transform-box"/>
    public CssKeyword? TransformBox { init => Set("transform-box", value); }

    /// <summary>设置元素变换的原点。（transform-origin）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>left</c>：水平方向取左边缘，相当于 0%。</description></item>
