    /// <para>常用值：<c>none</c>、<c>button</c>、<c>button-bevel</c>、<c>caret</c>、<c>checkbox</c>、<c>default-button</c>、<c>inner-spin-button</c>、<c>listbox</c>、<c>listitem</c>、<c>media-controls-background</c>、<c>media-controls-fullscreen-background</c>、<c>media-current-time-display</c>、<c>media-enter-fullscreen-button</c>、<c>media-exit-fullscreen-button</c>、<c>media-fullscreen-button</c>、<c>media-mute-button</c>、<c>media-overlay-play-button</c>、<c>media-play-button</c>、<c>media-seek-back-button</c>、<c>media-seek-forward-button</c>、<c>media-slider</c>、<c>media-sliderthumb</c>、<c>media-time-remaining-display</c>、<c>media-toggle-closed-captions-button</c>、<c>media-volume-slider</c>、<c>media-volume-slider-container</c>、<c>media-volume-sliderthumb</c>、<c>menulist</c>、<c>menulist-button</c>、<c>menulist-text</c>、<c>menulist-textfield</c>、<c>meter</c>、<c>progress-bar</c>、<c>progress-bar-value</c>、<c>push-button</c>、<c>radio</c>、<c>searchfield</c>、<c>searchfield-cancel-button</c>、<c>searchfield-decoration</c>、<c>searchfield-results-button</c>、<c>searchfield-results-decoration</c>、<c>slider-horizontal</c>、<c>slider-vertical</c>、<c>sliderthumb-horizontal</c>、<c>sliderthumb-vertical</c>、<c>square-button</c>、<c>textarea</c>、<c>textfield</c>、<c>apple-pay-button</c></para>
