    /// <item><description><c>vertical</c>：旧版弹性盒的子元素垂直排列，与 <c>WebkitLineClamp</c> 配合实现多行截断。</description></item>
    /// </list>
    /// </remarks>
    public CssKeyword? WebkitBoxOrient { init => Set("-webkit-box-orient", value); }

    /// <summary>WebKit 在 macOS 上的字体抗锯齿方式（-webkit-font-smoothing），非标准；antialiased 让文字显得更细。</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>antialiased</c>：在 macOS 上改用灰度抗锯齿，文字比默认的子像素渲染更细；非标准，仅 macOS 的 WebKit/Blink 生效。</description></item>
    /// </list>
    /// </remarks>
    public CssKeyword? WebkitFontSmoothing { init => Set("-webkit-font-smoothing", value); }

    /// <summary>限制多行文本显示的行数；需要同时写 display: '-webkit-box'、WebkitBoxOrient: 'vertical' 和 overflow: 'hidden'，不删除文本内容。（-webkit-line-clamp）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>none</c>：不限制显示行数，文本完整显示，是默认值。</description></item>
    /// </list>
    /// <para>数字值不加单位；初始值 <c>none</c>；不继承。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/-webkit-line-clamp"/>
    public CssValue? WebkitLineClamp { init => Set("-webkit-line-clamp", value, NumberUnit.None); }

    /// <summary>带 WebKit 前缀的遮罩图像（-webkit-mask-image）；标准写法是 maskImage，只在兼容旧版 Safari 时使用。</summary>
    /// <remarks>
    /// <para>初始值 <c>none</c>；不继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/mask-image"/>
    public CssKeyword? WebkitMaskImage { init => Set("-webkit-mask-image", value); }

    /// <summary>移动端点击元素时出现的高亮颜色（-webkit-tap-highlight-color），非标准；设为 transparent 可去掉高亮。</summary>
    /// <remarks>
    /// <para>初始值 <c>black</c>；继承；非标准。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/-webkit-tap-highlight-color"/>
    public CssColor? WebkitTapHighlightColor { init => Set("-webkit-tap-highlight-color", value); }

    /// <summary>文字的填充颜色（-webkit-text-fill-color），优先于 color；常与 backgroundClip: text 配合做渐变文字。</summary>
    /// <remarks>
    /// <para>初始值 <c>currentcolor</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/-webkit-text-fill-color"/>
    public CssColor? WebkitTextFillColor { init => Set("-webkit-text-fill-color", value); }

    /// <summary>文字描边的颜色（-webkit-text-stroke-color）。</summary>
    /// <remarks>
    /// <para>初始值 <c>currentcolor</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/-webkit-text-stroke-color"/>
    public CssColor? WebkitTextStrokeColor { init => Set("-webkit-text-stroke-color", value); }

    /// <summary>文字描边的宽度（-webkit-text-stroke-width）。</summary>
    /// <remarks>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>0</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/-webkit-text-stroke-width"/>
    public CssLength? WebkitTextStrokeWidth { init => Set("-webkit-text-stroke-width", value); }

    /// <summary>设置空白折叠和换行处理方式。（white-space）</summary>
    /// <remarks>
    /// <para>同时影响空白折叠和软换行。它不负责给溢出内容添加省略号。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：折叠连续空白和源换行，允许软换行。</description></item>
    /// <item><description><c>nowrap</c>：折叠空白并禁止软换行；不会自行生成省略号。pre 也不进行普通软换行，但会保留连续空白。</description></item>
    /// <item><description><c>pre</c>：保留空白和源换行，不进行普通软换行。</description></item>
    /// <item><description><c>pre-wrap</c>：保留空白和源换行，同时允许软换行。pre 不进行普通软换行；pre-line 会折叠连续空格。</description></item>
    /// <item><description><c>pre-line</c>：折叠空格等空白但保留源换行，同时允许软换行。</description></item>
    /// </list>
    /// <para>适用场景：单行标签、保留换行的用户文本和代码片段。</para>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/white-space"/>
    public CssKeyword? WhiteSpace { init => Set("white-space", value); }

    /// <summary>设置分页或分栏断点后需保留的最少行数。（widows）</summary>
    /// <remarks>
    /// <para>数字值不加单位；初始值 <c>2</c>；继承；Baseline：尚未在所有主流浏览器可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/widows"/>
    public CssValue? Widows { init => Set("widows", value, NumberUnit.None); }

    /// <summary>设置元素的物理宽度，盒子范围受 box-sizing 影响。（width）</summary>
    /// <remarks>
    /// <para>百分比依据包含块解析；auto、内部尺寸和最小/最大约束共同决定最终使用尺寸。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：让布局算法决定尺寸，不保证等于父元素尺寸。</description></item>
    /// <item><description><c>min-content</c>：采用内容的最小内部尺寸，文字会考虑可用的软换行机会。</description></item>
    /// <item><description><c>max-content</c>：采用内容的最大内部尺寸，通常不进行软换行。</description></item>
    /// <item><description><c>fit-content</c>：在最小和最大内部尺寸之间按可用空间夹取尺寸。</description></item>
    /// </list>
    /// <para>适用场景：控制物理宽度；支持书写模式的布局可优先考虑 inline-size。</para>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>auto</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/width"/>
    public CssLength? Width { init => Set("width", value); }

    /// <summary>提前告知浏览器可能发生变化的属性，便于准备优化资源。（will-change）</summary>
    /// <remarks>
    /// <para>仅对即将发生的变化短期使用；长期或大量声明可能占用额外资源，并提前改变层叠上下文。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：不提前告知任何即将变化的属性，由浏览器按常规方式处理，是默认值。</description></item>
    /// </list>
    /// <para>初始值 <c>auto</c>；不继承；Baseline：2022 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/will-change"/>
    public CssKeyword? WillChange { init => Set("will-change", value); }

    /// <summary>设置单词内部或文字之间的断行规则。（word-break）</summary>
    /// <remarks>
    /// <para>按字符和语言控制断行。仅需避免超长单词溢出时，通常先考虑 overflow-wrap。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：按语言的默认断行规则处理。</description></item>
    /// <item><description><c>break-all</c>：允许在更多字符间断行以防溢出，可能拆开普通单词。</description></item>
    /// <item><description><c>keep-all</c>：限制中日韩文字内部断行，其他文字仍按正常规则处理。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/word-break"/>
    public CssKeyword? WordBreak { init => Set("word-break", value); }

    /// <summary>设置单词或词间分隔符的额外间距。（word-spacing）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不额外增加词间距，使用字体自身的间距，计算值为 0。</description></item>
    /// </list>
    /// <para>数字值自动加 <c>px</c>；初始值 <c>normal</c>；继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/word-spacing"/>
    public CssLength? WordSpacing { init => Set("word-spacing", value); }

    /// <summary>设置长文本的额外换行行为；是 overflow-wrap 的兼容名称。（word-wrap）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>break-word</c>：没有其他断行机会时，允许在单词内部任意位置折断，防止长单词溢出容器。</description></item>
    /// <item><description><c>normal</c>：只在正常断点处换行，过长的单词会溢出容器。</description></item>
    /// </list>
    /// <para>初始值 <c>normal</c>；继承。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/overflow-wrap"/>
    public CssKeyword? WordWrap { init => Set("word-wrap", value); }

    /// <summary>设置水平或竖直书写模式，以及行和块的推进方向。（writing-mode）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>horizontal-tb</c>：文字水平排列，行从上到下堆叠，是大多数语言的默认模式。</description></item>
    /// <item><description><c>lr</c>：SVG 1.1 旧值，按 <c>horizontal-tb</c> 处理；已废弃，改用 <c>horizontal-tb</c>。</description></item>
    /// <item><description><c>lr-tb</c>：SVG 1.1 旧值，水平从左到右、行从上到下，按 <c>horizontal-tb</c> 处理；已废弃，改用 <c>horizontal-tb</c>。</description></item>
    /// <item><description><c>rl</c>：SVG 1.1 旧值，按 <c>horizontal-tb</c> 处理；已废弃，改用 <c>horizontal-tb</c> 搭配 <c>direction</c>。</description></item>
    /// <item><description><c>rl-tb</c>：SVG 1.1 旧值，水平从右到左、行从上到下，按 <c>horizontal-tb</c> 处理；已废弃，改用 <c>horizontal-tb</c> 搭配 <c>direction</c>。</description></item>
    /// <item><description><c>sideways-lr</c>：文字整体逆时针旋转 90° 竖排，行从左到右堆叠，适合侧向标签。</description></item>
    /// <item><description><c>sideways-rl</c>：文字整体顺时针旋转 90° 竖排，行从右到左堆叠。</description></item>
    /// <item><description><c>tb</c>：SVG 1.1 旧值，按 <c>vertical-rl</c> 处理；已废弃，改用 <c>vertical-rl</c>。</description></item>
    /// <item><description><c>tb-rl</c>：SVG 1.1 旧值，垂直排列、行从右到左，按 <c>vertical-rl</c> 处理；已废弃，改用 <c>vertical-rl</c>。</description></item>
    /// <item><description><c>vertical-lr</c>：文字竖排，行从左到右堆叠，蒙古文用这种排法；字形朝向由 <c>text-orientation</c> 决定。</description></item>
    /// <item><description><c>vertical-rl</c>：文字垂直排列，行从右到左堆叠，常用于中日韩文字竖排。</description></item>
    /// </list>
    /// <para>初始值 <c>horizontal-tb</c>；继承；Baseline：2019 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/writing-mode"/>
    public CssKeyword? WritingMode { init => Set("writing-mode", value); }

    /// <summary>设置元素在所属层叠上下文中的层叠级别。（z-index）</summary>
    /// <remarks>
    /// <para>数值只在所属层叠上下文内比较；更大的数值不保证盖过其他层叠上下文。Flex/Grid 项目也可以使用 z-index。</para>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>auto</c>：层叠级别与父级相同（视为 0），且不会因此创建新的层叠上下文。</description></item>
    /// </list>
    /// <para>适用场景：控制同一层叠上下文中的浮层顺序，排查遮挡时先确认祖先层叠上下文。</para>
    /// <para>数字值不加单位；初始值 <c>auto</c>；不继承；Baseline：2018 年起广泛可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/z-index"/>
    public CssValue? ZIndex { init => Set("z-index", value, NumberUnit.None); }

    /// <summary>设置元素及其布局的缩放比例，与 transform:scale 的布局行为不同。（zoom）</summary>
    /// <remarks>
    /// <para>常用值：</para>
    /// <list type="bullet">
    /// <item><description><c>normal</c>：不额外缩放（等同 <c>1</c>），沿用祖先已有的缩放，是默认值。</description></item>
    /// <item><description><c>reset</c>：把该元素的有效缩放重置为 1，忽略祖先 <c>zoom</c> 带来的缩放；浏览器支持有限。</description></item>
    /// </list>
    /// <para>数字值不加单位；初始值 <c>1</c>；不继承；Baseline：2024 年起新近可用。</para>
    /// </remarks>
    /// <seealso href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/zoom"/>
    public CssValue? Zoom { init => Set("zoom", value, NumberUnit.None); }
}
